```
function gameOfLife(canvasId, gridWidth = 50, gridHeight = 50) {
  constgave = document.getElementById(canvasId);
  const ctx = gave.getContext("2d");
  const cellWidth = gave.width / gridWidth;
  const cellHeight = gave.height / gridHeight;
  let grid = Array.from({ length: gridHeight }, () =>
    Array.from({ length: gridWidth }, () => 0)
  );
  let nextGrid = Array.from({ length: gridHeight }, () =>
    Array.from({ length: gridWidth }, () => 0)
  );
  let generation = 0;
  let speed = 10; // Default speed: 10 generations per second
  let isRunning = false;
  let pattern = "none"; // "none", "glider", "blinker", "gosper", "pulsar"
  const emojis = [
    "",
    "⚫",
    "⚪",
    "🟩",
    "🟦",
    "🟪",
    "🟧",
    "🟨",
    "🟦🟧",
    "🟪🟧",
    "🟧🟪",
  ];

  // Fill grid with the selected pattern
  function fillPattern() {
    if (pattern === "glider") {
      grid[1][1] = 1;
      grid[2][2] = 1;
      grid[0][0] = 1;
      grid[1][0] = 1;
      grid[2][1] = 1;
    } else if (pattern === "blinker") {
      grid[Math.floor(gridHeight / 2)][0] = 1;
      grid[Math.floor(gridHeight / 2)][1] = 1;
      grid[Math.floor(gridHeight / 2)][2] = 1;
    } else if (pattern === "gosper") {
      grid[5][5] = 1;
      grid[6][5] = 1;
      grid[5][6] = 1;
      grid[4][7] = 1;
      grid[5][7] = 1;
      grid[6][7] = 1;
      grid[7][6] = 1;
      grid[5][4] = 1;
      grid[5][3] = 1;
      grid[4][3] = 1;
      grid[4][4] = 1;
      grid[3][3] = 1;
      grid[3][4] = 1;
      grid[6][4] = 1;
      grid[6][3] = 1;
    } else if (pattern === "pulsar") {
      grid[1][1] = 1;
      grid[1][2] = 1;
      grid[2][1] = 1;
      grid[2][2] = 1;
      grid[10][1] = 1;
      grid[10][2] = 1;
      grid[11][1] = 1;
      grid[11][2] = 1;
      grid[1][10] = 1;
      grid[1][11] = 1;
      grid[2][10] = 1;
      grid[2][11] = 1;
      grid[10][10] = 1;
      grid[10][11] = 1;
      grid[11][10] = 1;
      grid[11][11] = 1;
    }
  }

  // Update the next grid based on current grid
  function updateGrid() {
    for (let y = 0; y < gridHeight; y++) {
      for (let x = 0; x < gridWidth; x++) {
        let neighbors = 0;
        for (let i = -1; i <= 1; i++) {
          for (let j = -1; j <= 1; j++) {
            if (i === 0 && j === 0) continue;
            const newX = (x + i + gridWidth) % gridWidth;
            const newY = (y + j + gridHeight) % gridHeight;
            neighbors += grid[newX][newY];
          }
        }
        if (grid[x][y] === 0 && neighbors === 3) {
          nextGrid[x][y] = 1;
        } else if (grid[x][y] === 1 && (neighbors < 2 || neighbors > 3)) {
          nextGrid[x][y] = 0;
        } else {
          nextGrid[x][y] = grid[x][y];
        }
      }
    }
  }

  // Draw the grid on the canvas
  function drawGrid() {
    ctx.clearRect(0, 0, gave.width, gave.height);
    for (let y = 0; y < gridHeight; y++) {
      for (let x = 0; x < gridWidth; x++) {
        const emoji = emojis[nextGrid[x][y]];
        ctx.fillStyle = emoji === "" ? "#000" : emoji === "⚫" ? "#000" : "#fff";
        ctx.fillRect(x * cellWidth, y * cellHeight, cellWidth, cellHeight);
        ctx.font = "12px Arial";
        ctx.fillStyle = "#000";
        ctx.fillText(
          nextGrid[x][y],
          x * cellWidth + cellWidth / 2,
          y * cellHeight + cellHeight / 2
        );
      }
    }
  }

  // Initialize the grid and set up event listeners
  function init() {
    fillPattern();
    setInterval(() => {
      if (isRunning) {
        updateGrid();
        generation++;
        drawGrid();
      }
    }, 1000 / speed);
    gave.addEventListener("click", (e) => {
      const x = Math.floor(e.offsetX / cellWidth);
      const y = Math.floor(e.offsetY / cellHeight);
      grid[x][y] = grid[x][y] === 1 ? 0 : 1;
      updateGrid();
      drawGrid();
    });
    document.getElementById("pattern").addEventListener("change", (e) => {
      grid = Array.from({ length: gridHeight }, () =>
        Array.from({ length: gridWidth }, () => 0)
      );
      pattern = e.target.value;
      fillPattern();
      updateGrid();
      drawGrid();
    });
    document.getElementById("randomize").addEventListener("click", () => {
      grid = Array.from({ length: gridHeight }, () =>
        Array.from({ length: gridWidth }, () =>
          Math.random() < 0.2 ? 1 : 0
        )
      );
      updateGrid();
      drawGrid();
    });
    document.getElementById("clear").addEventListener("click", () => {
      grid = Array.from({ length: gridHeight }, () =>
        Array.from({ length: gridWidth }, () => 0)
      );
      updateGrid();
      drawGrid();
    });
    document.getElementById("start-pause").addEventListener("click", () => {
      isRunning = !isRunning;
    });
    document.getElementById("speed").addEventListener("input", (e) => {
      speed = e.target.value;
    });
  }

  init();
}

// Usage example:
gameOfLife("game-of-life", 100, 100);

